import numpy as np
import pytest

from data.fetch_options import load_market_data
from pricing.calibration import calibrate_heston, flat_bs_benchmark, heston_implied_vols, rmse_points
from pricing.heston import HestonParams


def synthetic_surface(params: HestonParams, r: float = 0.03):
    """A small grid of options with implied vols generated by the model itself."""
    maturities = np.array([0.1, 0.25, 0.5, 1.0])
    moneyness = np.linspace(-0.25, 0.15, 9)
    T = np.repeat(maturities, len(moneyness))
    F = 100.0 * np.exp(r * T)
    K = F * np.exp(np.tile(moneyness, len(maturities)))
    return F, K, T, heston_implied_vols(F, K, T, r, params), r


def test_calibration_recovers_known_parameters():
    true = HestonParams(v0=0.04, kappa=2.0, theta=0.06, sigma_v=0.5, rho=-0.7)
    F, K, T, iv, r = synthetic_surface(true)
    fit = calibrate_heston(F, K, T, iv, r)
    p = fit.params
    assert fit.rmse < 0.01
    assert p.v0 == pytest.approx(true.v0, abs=2e-3)
    assert p.theta == pytest.approx(true.theta, abs=3e-3)
    assert p.rho == pytest.approx(true.rho, abs=0.03)
    assert p.kappa == pytest.approx(true.kappa, rel=0.15)
    assert p.sigma_v == pytest.approx(true.sigma_v, rel=0.10)


def test_flat_benchmark_is_the_mean_vol_per_maturity():
    T = np.array([0.5, 0.5, 1.0, 1.0, 1.0])
    iv = np.array([0.20, 0.30, 0.10, 0.20, 0.30])
    assert flat_bs_benchmark(T, iv) == pytest.approx([0.25, 0.25, 0.20, 0.20, 0.20])


def test_heston_beats_flat_black_scholes_on_the_sample_chain():
    quotes, meta = load_market_data(r=0.05, source="sample")
    F, K, T, iv = (quotes[c].to_numpy() for c in ("forward", "strike", "T", "iv"))
    fit = calibrate_heston(F, K, T, iv, meta["r"])
    flat_rmse = rmse_points(flat_bs_benchmark(T, iv) - iv)
    assert fit.converged
    assert fit.rmse < flat_rmse / 3
    # equity index smiles slope downwards: the fitted correlation must be negative
    assert fit.params.rho < 0
